yes(813,'C','Zinc is +2 in ZnO and 0 in elemental Zn. The decrease in oxidation number means zinc is reduced; carbon monoxide is oxidised to carbon dioxide.',[RX],question='In ZnO + CO → Zn + CO₂, zinc has been',options=['Displaced','Oxidised','Reduced','Decomposed'],audit='Restored complete reaction from PDF68 preceding equation.',check='zinc-reduction')
yes(814,'D','CaCO₃ + 2HCl → CaCl₂ + CO₂ + H₂O. The carbonate molar mass is 100 g mol⁻¹, so 2 g gives 0.020 mol CO₂. Volume = 0.020 × 22.4 = 0.448 dm³ = 448 cm³.',[RX],question='What volume of CO₂ at s.t.p. is formed when 2 g of CaCO₃ reacts completely with excess HCl? [Ca = 40, C = 12, O = 16; molar gas volume = 22.4 dm³ mol⁻¹]',options=['224 cm³','112 cm³','2240 cm³','448 cm³'],audit='Corrected B→D independently; made complete reaction/excess condition explicit.',check='carbonate-gas')
yes(815,'A','Sublimation is the direct change from solid to gas without passing through the liquid state. Evaporation begins with a liquid, while crystallisation forms a solid.',[REB],question='A solid changes directly into gas on heating without becoming liquid. This process is',options=['Sublimation','Crystallisation','Distillation','Evaporation'])
